// Deliberately NOT a "use server" module: server actions live upstream and do the auth.
import { prisma } from "@/lib/db"
import { recordSystemAudit } from "@/lib/audit"
import { listWorkspaceBills } from "@/models/bills"
import { formatZaEftCsv, paymentRunFilename, totalsByCurrency, type PaymentInstruction } from "@/lib/payments/za-eft-csv"
import { buildRemittanceAdvices, type RemittanceAdvice } from "@/lib/payments/remittance"
import type { Prisma } from "@/prisma/client"

export type PreparePaymentRunResult = {
  run: { id: string; filename: string; itemCount: number; totalsByCurrency: Record<string, number> }
  csv: string
  advices: RemittanceAdvice[]
}

/** WP-AP2: prepares a payment run from the given bills for this workspace. Filters out bills
 * that are already in an active (non-cancelled) run so the same invoice isn't paid twice, and
 * returns the generated CSV + per-supplier remittance advices. Never itself moves money — the
 * user takes the CSV to their bank's own portal.
 *
 * Bills without a supplier bank account are dropped from the run rather than blocking it — the
 * caller renders the "N bills need a bank account" hint separately. */
export async function preparePaymentRun(input: {
  workspaceId: string
  actorId: string
  documentIds: string[]
  now?: Date
}): Promise<PreparePaymentRunResult> {
  const now = input.now ?? new Date()
  if (input.documentIds.length === 0) throw new Error("no_documents_selected")

  const { bills } = await listWorkspaceBills({ workspaceId: input.workspaceId, limit: 1000 })
  const selectedIds = new Set(input.documentIds)
  const selected = bills.filter((b) => selectedIds.has(b.documentId))

  const alreadyInRun = await prisma.paymentRunItem.findMany({
    where: { workspaceId: input.workspaceId, documentId: { in: input.documentIds }, active: true },
    select: { documentId: true },
  })
  const alreadyIds = new Set(alreadyInRun.map((r) => r.documentId).filter(Boolean) as string[])

  const suppliers = await prisma.supplier.findMany({
    where: { workspaceId: input.workspaceId, id: { in: selected.map((b) => b.supplierId).filter((id): id is string => id !== null) } },
    select: { id: true, iban: true, bankDetails: true },
  })
  const bankBySupplier = new Map(suppliers.map((s) => {
    const details = (s.bankDetails ?? {}) as Record<string, unknown>
    const account = typeof details.account === "string" ? details.account : (typeof details.iban === "string" ? details.iban : (typeof s.iban === "string" ? s.iban : null))
    const branchCode = typeof details.branchCode === "string" ? details.branchCode : (typeof details.branch === "string" ? details.branch : null)
    return [s.id, { account, branchCode }]
  }))

  const instructions: PaymentInstruction[] = []
  const skipped: Array<{ documentId: string; reason: string }> = []
  for (const bill of selected) {
    if (alreadyIds.has(bill.documentId)) { skipped.push({ documentId: bill.documentId, reason: "already_in_active_run" }); continue }
    // #220: server-side defense in depth — the client already excludes a cancelled invoice from
    // payableDocumentIds, but a payment file is money leaving the workspace, so this doesn't rely
    // on that alone.
    if (bill.cancelledAt) { skipped.push({ documentId: bill.documentId, reason: "cancelled" }); continue }
    if (bill.total === null || bill.total <= 0) { skipped.push({ documentId: bill.documentId, reason: "missing_amount" }); continue }
    if (!bill.supplier) { skipped.push({ documentId: bill.documentId, reason: "missing_supplier" }); continue }
    const bank = bill.supplierId ? bankBySupplier.get(bill.supplierId) : null
    if (!bank?.account) { skipped.push({ documentId: bill.documentId, reason: "missing_bank_account" }); continue }
    instructions.push({
      documentId: bill.documentId,
      supplier: bill.supplier,
      bankAccountNumber: bank.account,
      branchCode: bank.branchCode ?? null,
      amount: bill.total,
      currencyCode: (bill.currencyCode ?? "ZAR").toUpperCase(),
      reference: bill.invoiceNumber ?? bill.documentId.slice(0, 8),
    })
  }

  if (instructions.length === 0) throw new Error("no_payable_bills_after_filtering")

  const csv = formatZaEftCsv(instructions)
  const filename = paymentRunFilename(now)
  const totals = totalsByCurrency(instructions)

  const workspace = await prisma.workspace.findFirst({ where: { id: input.workspaceId }, select: { name: true } })
  const advices = buildRemittanceAdvices(instructions, { name: workspace?.name ?? "Your workspace", runDate: now })

  const run = await prisma.paymentRun.create({
    data: {
      workspaceId: input.workspaceId,
      createdById: input.actorId,
      status: "draft",
      filename,
      itemCount: instructions.length,
      totalsJson: totals as unknown as Prisma.InputJsonValue,
      items: {
        create: instructions.map((ins) => ({
          workspaceId: input.workspaceId,
          documentId: ins.documentId,
          supplier: ins.supplier,
          amount: ins.amount,
          currencyCode: ins.currencyCode,
          reference: ins.reference,
        })),
      },
    },
    select: { id: true, filename: true, itemCount: true },
  })

  await recordSystemAudit({
    workspaceId: input.workspaceId,
    type: "payment_run_prepared",
    detail: { runId: run.id, itemCount: run.itemCount, skipped, totalsByCurrency: totals },
  })

  return {
    run: { id: run.id, filename: run.filename ?? filename, itemCount: run.itemCount, totalsByCurrency: totals },
    csv,
    advices,
  }
}

/** Marks a draft run as sent to the bank. Called from the "I've uploaded it" server action, so
 * the aging view knows not to keep flagging the bills as unpaid until the ledger sync catches
 * up. Ledger reconciliation itself is unchanged — bank-match matches the payment lines back to
 * these documents through their invoice references, exactly like it does today for manually-paid
 * bills. */
export async function markPaymentRunSent(input: { workspaceId: string; runId: string; actorId: string }) {
  const run = await prisma.paymentRun.findFirst({ where: { id: input.runId, workspaceId: input.workspaceId }, select: { id: true, status: true } })
  if (!run) throw new Error("payment_run_not_found")
  if (run.status !== "draft") throw new Error("payment_run_not_draft")
  const updated = await prisma.paymentRun.update({
    where: { id: run.id },
    data: { status: "sent", sentAt: new Date() },
    select: { id: true, status: true, sentAt: true },
  })
  await recordSystemAudit({
    workspaceId: input.workspaceId,
    type: "payment_run_sent",
    detail: { runId: run.id, actorId: input.actorId },
  })
  return updated
}

export async function listPaymentRuns(workspaceId: string, opts: { limit?: number } = {}) {
  return prisma.paymentRun.findMany({
    where: { workspaceId },
    orderBy: { createdAt: "desc" },
    take: opts.limit ?? 50,
    select: { id: true, filename: true, status: true, itemCount: true, totalsJson: true, sentAt: true, createdAt: true },
  })
}

"use server"

import { getCurrentUser } from "@/lib/auth"
import { requireWorkspaceRole } from "@/models/workspaces"
import { preparePaymentRun } from "@/models/payment-runs"
import { revalidatePath } from "next/cache"
import { redirect } from "next/navigation"

/** WP-AP2: Bills-page server action to prepare a ZA EFT payment file from a set of bill IDs.
 * The action creates the PaymentRun + items and redirects to the download route, which
 * regenerates the CSV from the stored rows. Owner-only — payments are a controller action. */
export async function preparePaymentRunAction(workspaceId: string, formData: FormData) {
  const user = await getCurrentUser()
  const membership = await requireWorkspaceRole(workspaceId, user.id)
  if (membership.role !== "owner") throw new Error("owner_only")

  const documentIds = formData.getAll("documentId").map(String).filter(Boolean)
  if (!documentIds.length) throw new Error("no_documents_selected")

  const { run } = await preparePaymentRun({ workspaceId, actorId: user.id, documentIds })
  revalidatePath(`/workspaces/${workspaceId}/bills`)
  redirect(`/api/workspaces/${workspaceId}/payment-runs/${run.id}/download`)
}

import type { AgingBucket } from "@/lib/bills/due-date"
import type { BillsSummary } from "@/models/bills"
import { Clock3 } from "lucide-react"
import Link from "next/link"

/** #225: the per-bucket aging totals that left the Invoices header. One panel, not six cards:
 * a proportional bar of outstanding money by bucket, then one row per bucket that links into the
 * Invoices queue with that bucket's Aging chip already applied, so every number here has
 * somewhere to go. Counts only unpaid bills — a paid invoice has no age worth reporting. */
const BUCKETS: (AgingBucket | "unknown")[] = ["current", "1-30", "31-60", "61-90", "90+", "unknown"]

const BUCKET: Record<AgingBucket | "unknown", { label: string; param: string; bar: string }> = {
  current: { label: "Not yet due", param: "current", bar: "bg-emerald-500" },
  "1-30": { label: "1–30 days overdue", param: "1-30", bar: "bg-amber-400" },
  "31-60": { label: "31–60 days overdue", param: "31-60", bar: "bg-amber-500" },
  "61-90": { label: "61–90 days overdue", param: "61-90", bar: "bg-orange-500" },
  "90+": { label: "90+ days overdue", param: "90+", bar: "bg-red-500" },
  unknown: { label: "No due date", param: "none", bar: "bg-slate-300" },
}

export function AgingSummary({ workspaceId, summary, formatMoney }: {
  workspaceId: string
  summary: BillsSummary
  formatMoney: (value: number) => string
}) {
  const openCount = BUCKETS.reduce((sum, bucket) => sum + summary[bucket].count, 0)
  const outstanding = BUCKETS.reduce((sum, bucket) => sum + summary[bucket].total, 0)
  const overdue = (["1-30", "31-60", "61-90", "90+"] as const).reduce((sum, bucket) => sum + summary[bucket].total, 0)
  const queueHref = (param?: string) => `/workspaces/${workspaceId}/invoices?unpaid=1${param ? `&aging=${param}` : ""}`

  return <section aria-labelledby="aging-heading" className="rounded-2xl border border-[#e6ebf1] bg-white p-[18px] shadow-panel lg:p-5">
    <div className="mb-3.5 flex flex-wrap items-center gap-2">
      <span className="flex h-8 w-8 items-center justify-center rounded-lg bg-amber-50 text-amber-700"><Clock3 className="h-[17px] w-[17px]" /></span>
      <h2 id="aging-heading" className="text-[15px] font-bold text-slate-900">Open invoices by age</h2>
      {openCount > 0 && <Link href={queueHref()} className="ml-auto text-[13px] font-semibold text-emerald-700 hover:text-emerald-800">Open Invoices</Link>}
    </div>

    {openCount === 0 ? <p className="py-6 text-center text-sm text-slate-500">No unpaid invoices right now.</p> : <>
      <p className="text-[13.5px] text-slate-600">
        <span className="font-bold tabular-nums text-slate-900">{formatMoney(outstanding)}</span> outstanding across {openCount} invoice{openCount === 1 ? "" : "s"}
        {overdue > 0 && <> · <span className="font-semibold tabular-nums text-red-700">{formatMoney(overdue)}</span> overdue</>}
      </p>

      {outstanding > 0 && <div className="mt-3 flex h-2 w-full overflow-hidden rounded-full bg-slate-100" aria-hidden="true">
        {BUCKETS.map((bucket) => {
          const share = summary[bucket].total / outstanding
          return share > 0 ? <div key={bucket} className={BUCKET[bucket].bar} style={{ width: `${share * 100}%` }} /> : null
        })}
      </div>}

      <ul className="mt-3 divide-y divide-[#eef2f6]">
        {BUCKETS.map((bucket) => {
          const data = summary[bucket]
          if (data.count === 0) return null
          return <li key={bucket}>
            <Link href={queueHref(BUCKET[bucket].param)} className="flex items-center gap-2.5 py-2 text-[13.5px] hover:text-emerald-800">
              <span className={`h-2.5 w-2.5 shrink-0 rounded-full ${BUCKET[bucket].bar}`} aria-hidden="true" />
              <span className="min-w-0 flex-1 truncate text-slate-700">{BUCKET[bucket].label}</span>
              <span className="w-8 shrink-0 text-right tabular-nums text-slate-500">{data.count}</span>
              <span className="w-[92px] shrink-0 text-right font-semibold tabular-nums text-slate-900">{data.total ? formatMoney(data.total) : "—"}</span>
            </Link>
          </li>
        })}
      </ul>
    </>}
  </section>
}

// Controls (the touchless-automation module's nav item) is hoisted out of the module bucket
// into the primary spine, directly under the typed intake group: it is the levers that govern the document
// pipeline, so adjacency to the pipeline it controls is the information architecture.
const controlsItem = moduleWorkItems.find((item) => item.href === `${base}/automation`)
// The review-queue module's "Review" item is dropped (#238): since #225 every queue is the
// review surface, so a second entry for the same job was a second grammar.
const otherModuleItems = moduleWorkItems.filter((item) => item.href !== `${base}/review` && item.href !== `${base}/automation`)

// Primary spine, in workflow order: the four typed intake destinations, then Exceptions
// (escalated work needing attention, per #210 — organize: same tier as the typed destinations
// by weight/badge treatment, not paired with any of them since it has no document-type sibling
// and cuts across all four), then Controls (their governing levers), Finance (booked outcome),
// and Archive (the permanent record everything lands in) closing the group.
const typedDestinationGroups = [
  [
    { href: `${base}/invoices`, label: "Invoices", icon: Receipt, exact: false },
    { href: `${base}/purchase-orders`, label: "Purchase Orders", icon: ClipboardCheck, exact: false },
  ],
  [
    { href: `${base}/receipts`, label: "Receipts", icon: Receipt, exact: false },
    { href: `${base}/bank-statements`, label: "Bank Statements", icon: Landmark, exact: false },
  ],
]
const exceptionsItem = { href: `${base}/exceptions`, label: "Exceptions", icon: AlertTriangle, exact: false, badge: openExceptionsCount > 0 ? openExceptionsCount : undefined }
const primaryItems = [
  exceptionsItem,
  ...(controlsItem ? [controlsItem] : []),
  ...(accountingEnabled ? [{ href: `${base}/finance`, label: "Finance", icon: Landmark, exact: false, badge: financePushableCount > 0 ? financePushableCount : undefined }] : []),
  // "Archive" is the accountant's own word for the permanent source-document record (Dext and
  // Hubdoc both name this surface Archive). Route stays /library — same label-over-URL stance
  // as Controls (/automation) and Finance's /accounting redirect.
  { href: `${base}/library`, label: "Archive", icon: Library, exact: false, tourTarget: "library" as const },
]

// Secondary destinations: per-workspace module extras only. Under a hairline, no caption — the
// divider is the sectioning.
const secondaryItems = otherModuleItems

const bottomItems = [
  { href: `${base}/settings/workspace`, label: "Settings", icon: Settings, exact: false },
  { href: `${base}/activity`, label: "Activity", icon: History, exact: false },
  { href: `${base}/health`, label: "Health Checks", icon: HeartPulse, exact: false },
]

// Sum across primary badges tells us whether the TODAY label is a promise or a reward. When the
// total is zero every primary is quiet, and the "you're caught up" line reads under the group
// instead of a promise the badges are supposed to keep.
const todayTotal = (pipelineReviewCount || 0) + (accountingEnabled ? (financePushableCount || 0) : 0) + (openExceptionsCount || 0)

const isActive = (item: { href: string; label: string; exact: boolean }) => item.exact

/** Pure due-date inference for AP aging. When an extracted invoice carries an explicit `due_date`
 * that is what wins; when it doesn't, the supplier's paymentTermsDays (WP-AP2) applied to the
 * invoice date is the fallback. Null when neither signal is available.
 *
 * Kept pure (no Prisma import) so the aging view, the bills API, and any future payment-run
 * pre-flight all speak the same due date without disagreeing on precedence. */

export function inferDueDate(input: {
  extractedDueDate: Date | null
  documentDate: Date | null
  supplierPaymentTermsDays: number | null
}): Date | null {
  if (input.extractedDueDate) return input.extractedDueDate
  if (input.documentDate && input.supplierPaymentTermsDays !== null && input.supplierPaymentTermsDays >= 0) {
    // Use UTC math so a call from a non-UTC test/env doesn't drift by a day at the day boundary.
    const inferred = new Date(input.documentDate)
    inferred.setUTCDate(inferred.getUTCDate() + input.supplierPaymentTermsDays)
    return inferred
  }
  return null
}

/** Aging bucket a due-date falls into as of `asOf`. `current` covers on-or-before-today-and-due;
 * negative days-past-due are treated as "not yet due" (current). */
export type AgingBucket = "current" | "1-30" | "31-60" | "61-90" | "90+"

export function agingBucket(dueDate: Date | null, asOf: Date): AgingBucket | null {
  if (!dueDate) return null
  const dueMs = dueDate.getTime()
  const nowMs = asOf.getTime()
  const daysPastDue = Math.floor((nowMs - dueMs) / (1000 * 60 * 60 * 24))
  if (daysPastDue <= 0) return "current"
  if (daysPastDue <= 30) return "1-30"
  if (daysPastDue <= 60) return "31-60"
  if (daysPastDue <= 90) return "61-90"
  return "90+"
}

export async function listWorkspaceBills(input: {
  workspaceId: string
  asOf?: Date
  limit?: number
  onlyBlocked?: boolean
  onlyUnpaid?: boolean
  /** #211's Status filter-chip group. "unreviewed"/"reviewed" map onto doc.status; there is no
   * model field for the taxonomy's Posted/Exported/Transferred values (no push/ledger status of
   * that shape exists), so "paid" stands in as the only real "closed" state. #220 adds "synced":
   * pushed successfully but not yet confirmed paid by the ledger — see BillRow.paymentStatus. */
  statusFilter?: "unreviewed" | "reviewed" | "synced" | "paid"
  /** #211's Invoice Approval filter-chip group. See BillRow.approvalStatus. */
  approvalFilter?: BillRow["approvalStatus"]
