// Assessment B runner for #229 — modelled on scripts/dev/detect-in-page.mjs.
// Usage: node runner.mjs <detectorPort> [--widths=1440,390]
import { createRequire } from "node:module"
const require = createRequire("/tmp/scratch229/package.json")
const { chromium } = require("playwright")

const port = process.argv[2] || "8400"
const widthsArg = (process.argv.find((a) => a.startsWith("--widths=")) || "--widths=1440,390").slice(9)
const widths = widthsArg.split(",").map(Number)
const URL = "http://localhost:3000/workspaces/af91555d-7450-4b21-a8ac-73db092617c8/invoices"
const OUT = "/tmp/scratch229"

const report = { widths: {}, errors: [] }

async function detect(page, label) {
  const consoleLines = []
  const onConsole = (m) => { const t = m.text(); if (/impeccable/i.test(t)) consoleLines.push(t.slice(0, 200)) }
  page.on("console", onConsole)
  let flat = []
  let err = null
  try {
    await page.addScriptTag({ url: `http://localhost:${port}/detect.js` })
    await page.waitForTimeout(3000)
    const findings = await page.evaluate(async () => {
      const f = await window.impeccableDetectAsync({})
      return f
    })
    for (const group of findings) {
      for (const f of group.findings ?? []) {
        flat.push({
          type: f.type || f.id,
          detail: (f.detail || f.snippet || "").slice(0, 160),
          el: group.el?.slice?.(0, 140) ?? group.selector ?? "",
        })
      }
    }
  } catch (e) {
    err = String(e.message).split("\n")[0]
  }
  page.off("console", onConsole)
  const byType = {}
  for (const f of flat) byType[f.type] = (byType[f.type] ?? 0) + 1
  return { label, count: flat.length, byType, findings: flat, consoleLines: consoleLines.slice(0, 10), error: err }
}

const browser = await chromium.launch()
for (const width of widths) {
  const W = { width, height: width < 600 ? 844 : 900 }
  const page = await browser.newPage({ viewport: W })
  const pageErrors = []
  page.on("pageerror", (e) => pageErrors.push(String(e.message).slice(0, 200)))
  const res = { viewport: W, pageErrors, bulk: {}, confirm: {}, keyboard: null }
  report.widths[width] = res
  try {
    await page.goto(URL, { waitUntil: "networkidle", timeout: 90000 })
    res.finalUrl = page.url()
    res.title = await page.title()
    await page.locator("table tbody tr").first().waitFor({ timeout: 60000 })
    res.rowCount = await page.locator("table tbody tr").count()

    // ---- bulk state ----
    const rowBoxes = page.locator("table tbody tr input[type=checkbox]")
    res.bulk.rowCheckboxCount = await rowBoxes.count()
    if (res.bulk.rowCheckboxCount < 2) throw new Error(`only ${res.bulk.rowCheckboxCount} row checkboxes`)
    // Record the first two rows' text so payability can be reasoned about.
    res.bulk.rowsSelected = []
    for (let i = 0; i < 2; i++) {
      res.bulk.rowsSelected.push((await page.locator("table tbody tr").nth(i).innerText()).replace(/\s+/g, " ").slice(0, 300))
      await rowBoxes.nth(i).check({ force: false })
    }
    await page.waitForTimeout(600)
    res.bulk.checkboxBox = await rowBoxes.first().evaluate((el) => { const r = el.getBoundingClientRect(); return { w: r.width, h: r.height } })
    res.bulk.checkboxLabel = await rowBoxes.first().evaluate((el) => el.getAttribute("aria-label"))

    // Find the bulk bar: the nearest ancestor block containing a button matching /Prepare payment run|selected/i.
    const bulkInfo = await page.evaluate(() => {
      const btns = [...document.querySelectorAll("button")]
      const anchor = btns.find((b) => /prepare payment run/i.test(b.textContent || "")) ||
        [...document.querySelectorAll("*")].find((n) => n.children.length < 12 && /\b\d+ selected\b/i.test(n.textContent || "") && n.querySelector("button"))
      if (!anchor) return { found: false, allButtonTexts: btns.map((b) => (b.textContent || "").trim()).filter(Boolean).slice(0, 60) }
      // climb to the container that holds several buttons and is positioned/flex
      let c = anchor.tagName === "BUTTON" ? anchor.parentElement : anchor
      for (let i = 0; i < 6 && c && c.parentElement; i++) {
        const cs = getComputedStyle(c)
        if (cs.position === "fixed" || cs.position === "sticky" || c.getAttribute("role") === "toolbar" || c.getAttribute("aria-label")) break
        if (c.querySelectorAll("button").length >= 2 && (cs.display === "flex" || cs.display === "grid")) break
        c = c.parentElement
      }
      const r = c.getBoundingClientRect()
      const cs = getComputedStyle(c)
      const buttons = [...c.querySelectorAll("button")].map((b) => {
        const br = b.getBoundingClientRect()
        return { text: (b.textContent || "").trim().replace(/\s+/g, " "), disabled: b.disabled || b.getAttribute("aria-disabled") === "true", box: { x: Math.round(br.x), y: Math.round(br.y), w: Math.round(br.width), h: Math.round(br.height) }, overflowsRight: br.right > window.innerWidth + 0.5 }
      })
      const prep = buttons.find((b) => /^prepare payment run/i.test(b.text))
      return {
        found: true,
        containerTag: c.tagName.toLowerCase(),
        containerClass: (c.className || "").toString().slice(0, 200),
        containerRole: c.getAttribute("role"), containerAria: c.getAttribute("aria-label"),
        position: cs.position,
        box: { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height), right: Math.round(r.right), bottom: Math.round(r.bottom) },
        overflowsViewport: r.right > window.innerWidth + 0.5 || r.left < -0.5,
        scrollWidth: c.scrollWidth, clientWidth: c.clientWidth,
        innerText: (c.innerText || "").replace(/\s+/g, " ").slice(0, 600),
        buttons,
        prepare: prep ? { text: prep.text, disabled: prep.disabled } : null,
      }
    })
    res.bulk.bar = bulkInfo
    await page.screenshot({ path: `${OUT}/bulk-${width}.png`, fullPage: false })
    await page.screenshot({ path: `${OUT}/bulk-${width}-full.png`, fullPage: true })
    res.bulk.detect = await detect(page, `bulk@${width}`)

    // ---- confirm state ----
    if (bulkInfo.found && bulkInfo.prepare && !bulkInfo.prepare.disabled) {
      const btn = page.getByRole("button", { name: /^prepare payment run/i }).first()
      await btn.click()
      const dlg = page.getByRole("dialog").first()
      await dlg.waitFor({ timeout: 15000 })
      await page.waitForTimeout(700)
      res.confirm.opened = true
      res.confirm.dialog = await dlg.evaluate((d) => {
        const r = d.getBoundingClientRect()
        const buttons = [...d.querySelectorAll("button")].map((b) => {
          const br = b.getBoundingClientRect()
          return { text: (b.textContent || "").trim().replace(/\s+/g, " "), disabled: b.disabled, ariaLabel: b.getAttribute("aria-label"), box: { x: Math.round(br.x), y: Math.round(br.y), w: Math.round(br.width), h: Math.round(br.height) }, overflowsRight: br.right > window.innerWidth + 0.5 }
        })
        return {
          ariaLabel: d.getAttribute("aria-label"), ariaLabelledBy: d.getAttribute("aria-labelledby"), ariaDescribedBy: d.getAttribute("aria-describedby"), ariaModal: d.getAttribute("aria-modal"),
          box: { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height), right: Math.round(r.right), bottom: Math.round(r.bottom) },
          overflowsViewport: r.right > window.innerWidth + 0.5 || r.bottom > window.innerHeight + 0.5 || r.left < -0.5 || r.top < -0.5,
          scrollHeight: d.scrollHeight, clientHeight: d.clientHeight,
          headings: [...d.querySelectorAll("h1,h2,h3")].map((h) => h.textContent.trim()),
          tables: [...d.querySelectorAll("table")].map((t) => t.innerText.replace(/\s+/g, " ").slice(0, 400)),
          innerText: d.innerText,
          buttons,
        }
      })
      await page.screenshot({ path: `${OUT}/confirm-${width}.png`, fullPage: false })
      res.confirm.detect = await detect(page, `confirm@${width}`)

      if (width >= 600) {
        // keyboard check — re-open cleanly after detector injection is not needed; focus state is as-opened.
        const active = () => page.evaluate(() => { const a = document.activeElement; return a ? { tag: a.tagName.toLowerCase(), text: (a.textContent || a.getAttribute("aria-label") || "").trim().replace(/\s+/g, " ").slice(0, 80), inDialog: !!a.closest("[role=dialog]") } : null })
        const kb = { activeOnOpen: await active(), tabStops: [] }
        for (let i = 0; i < 6; i++) { await page.keyboard.press("Tab"); await page.waitForTimeout(80); kb.tabStops.push(await active()) }
        kb.allStopsInDialog = kb.tabStops.every((s) => s && s.inDialog)
        res.keyboard = kb
      }
      await page.keyboard.press("Escape")
      await page.waitForTimeout(500)
      res.confirm.closedAfterEscape = (await page.getByRole("dialog").count()) === 0
    } else {
      res.confirm.opened = false
      res.confirm.reason = !bulkInfo.found ? "bulk bar not found" : !bulkInfo.prepare ? "no Prepare payment run button" : "button disabled"
    }
  } catch (e) {
    res.error = String(e.message).split("\n").slice(0, 3).join(" | ")
    try { await page.screenshot({ path: `${OUT}/error-${width}.png`, fullPage: false }) } catch {}
  }
  await page.close()
}
await browser.close()
console.log(JSON.stringify(report, null, 2))

