// Assessment B runner for #229 — modelled on scripts/dev/detect-in-page.mjs.
// Usage: node runner.mjs <detectorPort> [--widths=1440,390]
import { createRequire } from "node:module"
import fs from "node:fs"
const require = createRequire("/tmp/scratch229/package.json")
const { chromium } = require("playwright")

const port = process.argv[2] || "8400"
const widthsArg = (process.argv.find((a) => a.startsWith("--widths=")) || "--widths=1440,390").slice(9)
const widths = widthsArg.split(",").map(Number)
const URL = "http://localhost:3000/workspaces/af91555d-7450-4b21-a8ac-73db092617c8/invoices"
const OUT = "/tmp/scratch229"

const report = { startedAt: new Date().toISOString(), widths: {} }

async function detect(page, label) {
  const consoleLines = []
  const onConsole = (m) => { const t = m.text(); if (/impeccable/i.test(t)) consoleLines.push(t.slice(0, 200)) }
  page.on("console", onConsole)
  let flat = []
  let groups = 0
  let err = null
  try {
    await page.addScriptTag({ url: `http://localhost:${port}/detect.js` })
    await page.waitForTimeout(3000)
    const findings = await page.evaluate(async () => {
      const f = await window.impeccableDetectAsync({})
      const out = []
      for (const group of f) {
        const sel = group.el ?? group.selector ?? ""
        let text = null, tag = null, region = null
        try {
          const node = sel ? document.querySelector(sel) : null
          if (node) {
            tag = node.tagName.toLowerCase()
            text = (node.textContent || "").trim().replace(/\s+/g, " ").slice(0, 100)
            region = node.closest("[role=alertdialog]") ? "dialog" : node.closest("[aria-label='Bulk actions']") ? "bulk-bar" : node.closest("table") ? "table" : node.closest("nav,aside") ? "nav/rail" : node === document.body ? "body" : "other"
          }
        } catch {}
        for (const x of group.findings ?? []) out.push({ type: x.type || x.id, detail: (x.detail || x.snippet || "").slice(0, 200), el: String(sel).slice(0, 160), tag, text, region })
      }
      return { groups: f.length, out }
    })
    groups = findings.groups
    flat = findings.out
  } catch (e) {
    err = String(e.message).split("\n")[0]
  }
  page.off("console", onConsole)
  const byType = {}
  for (const f of flat) byType[f.type] = (byType[f.type] ?? 0) + 1
  return { label, groups, count: flat.length, byType, findings: flat, consoleLines: consoleLines.slice(0, 10), error: err }
}

async function openAndSelectTwo(browser, W) {
  const page = await browser.newPage({ viewport: W })
  const pageErrors = []
  page.on("pageerror", (e) => pageErrors.push(String(e.message).slice(0, 200)))
  await page.goto(URL, { waitUntil: "networkidle", timeout: 90000 })
  await page.locator("table tbody tr").first().waitFor({ timeout: 60000 })
  await page.mouse.move(W.width / 2, W.height / 2)
  await page.waitForTimeout(300)
  const rowBoxes = page.locator("table tbody tr input[type=checkbox]")
  const n = await rowBoxes.count()
  const rows = []
  for (let i = 0; i < Math.min(2, n); i++) {
    rows.push((await page.locator("table tbody tr").nth(i).innerText()).replace(/\s+/g, " ").slice(0, 300))
    await rowBoxes.nth(i).evaluate((el) => el.click())
    await page.waitForTimeout(250)
  }
  await page.waitForTimeout(500)
  const checkedCount = await page.locator("table tbody tr input[type=checkbox]:checked").count()
  return { page, pageErrors, rowCheckboxCount: n, rowsSelected: rows, checkedCount, rowCount: await page.locator("table tbody tr").count(), finalUrl: page.url() }
}

const measureBar = () => {
  const c = document.querySelector("[aria-label='Bulk actions']")
  if (!c) return { found: false, allButtonTexts: [...document.querySelectorAll("button")].map((b) => (b.textContent || "").trim()).filter(Boolean).slice(0, 60) }
  const r = c.getBoundingClientRect()
  const cs = getComputedStyle(c)
  const buttons = [...c.querySelectorAll("button")].map((b) => {
    const br = b.getBoundingClientRect(); const bs = getComputedStyle(b)
    return { text: (b.textContent || "").trim().replace(/\s+/g, " "), disabled: b.disabled || b.getAttribute("aria-disabled") === "true", box: { x: Math.round(br.x), y: Math.round(br.y), w: Math.round(br.width), h: Math.round(br.height) }, fontSize: bs.fontSize, paddingY: bs.paddingTop + "/" + bs.paddingBottom, overflowsRight: br.right > window.innerWidth + 0.5 }
  })
  const prep = buttons.find((b) => /^prepare payment run/i.test(b.text))
  const cb = document.querySelector("table tbody tr input[type=checkbox]")
  const cbr = cb ? cb.getBoundingClientRect() : null
  const rail = document.querySelector("aside, nav")
  const rr = rail ? rail.getBoundingClientRect() : null
  return {
    found: true, tag: c.tagName.toLowerCase(), className: (c.className || "").toString().slice(0, 200), role: c.getAttribute("role"), ariaLabel: c.getAttribute("aria-label"), position: cs.position,
    box: { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height), right: Math.round(r.right), bottom: Math.round(r.bottom) },
    overflowsViewport: r.right > window.innerWidth + 0.5 || r.left < -0.5, scrollWidth: c.scrollWidth, clientWidth: c.clientWidth, rowsWrapped: buttons.length > 1 && new Set(buttons.map((b) => b.box.y)).size > 1,
    innerText: (c.innerText || "").replace(/\s+/g, " ").slice(0, 600), buttons, prepare: prep ? { text: prep.text, disabled: prep.disabled } : null,
    checkbox: cbr ? { w: cbr.width, h: cbr.height, x: Math.round(cbr.x), y: Math.round(cbr.y), ariaLabel: cb.getAttribute("aria-label") } : null,
    rail: rr ? { tag: rail.tagName.toLowerCase(), x: Math.round(rr.x), w: Math.round(rr.width) } : null,
    viewport: { w: window.innerWidth, h: window.innerHeight },
  }
}

const measureDialog = (d) => {
  const r = d.getBoundingClientRect()
  const buttons = [...d.querySelectorAll("button")].map((b) => {
    const br = b.getBoundingClientRect()
    return { text: (b.textContent || "").trim().replace(/\s+/g, " "), disabled: b.disabled, ariaLabel: b.getAttribute("aria-label"), box: { x: Math.round(br.x), y: Math.round(br.y), w: Math.round(br.width), h: Math.round(br.height) }, overflowsRight: br.right > window.innerWidth + 0.5 }
  })
  const tables = [...d.querySelectorAll("table")].map((t) => {
    const tr = t.getBoundingClientRect(); const wrap = t.parentElement; const wr = wrap.getBoundingClientRect()
    return { text: t.innerText.replace(/\s+/g, " ").slice(0, 500), tableWidth: Math.round(tr.width), wrapperWidth: Math.round(wr.width), wrapperScrollWidth: wrap.scrollWidth, wrapperOverflowX: getComputedStyle(wrap).overflowX, tableRight: Math.round(tr.right), clippedByDialog: tr.right > r.right + 0.5 }
  })
  return {
    role: d.getAttribute("role"), ariaLabel: d.getAttribute("aria-label"), ariaLabelledBy: d.getAttribute("aria-labelledby"), ariaDescribedBy: d.getAttribute("aria-describedby"), ariaModal: d.getAttribute("aria-modal"),
    box: { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height), right: Math.round(r.right), bottom: Math.round(r.bottom) },
    overflowsViewport: r.right > window.innerWidth + 0.5 || r.bottom > window.innerHeight + 0.5 || r.left < -0.5 || r.top < -0.5,
    scrollHeight: d.scrollHeight, clientHeight: d.clientHeight,
    headings: [...d.querySelectorAll("h1,h2,h3")].map((h) => h.textContent.trim()),
    tables, innerText: d.innerText, buttons, viewport: { w: window.innerWidth, h: window.innerHeight },
  }
}

const browser = await chromium.launch()
for (const width of widths) {
  const W = { width, height: width < 600 ? 844 : 900 }
  const res = { viewport: W, bulk: {}, confirm: {}, keyboard: null }
  report.widths[width] = res

  // ---- bulk state (own page) ----
  try {
    const s = await openAndSelectTwo(browser, W)
    Object.assign(res.bulk, { rowCheckboxCount: s.rowCheckboxCount, rowsSelected: s.rowsSelected, checkedCount: s.checkedCount, rowCount: s.rowCount, finalUrl: s.finalUrl, pageErrors: s.pageErrors })
    res.bulk.bar = await s.page.evaluate(measureBar)
    await s.page.screenshot({ path: `${OUT}/bulk-${width}.png`, fullPage: false })
    await s.page.screenshot({ path: `${OUT}/bulk-${width}-full.png`, fullPage: true })
    res.bulk.detect = await detect(s.page, `bulk@${width}`)
    await s.page.close()
  } catch (e) { res.bulk.error = String(e.message).split("\n").slice(0, 3).join(" | ") }

  // ---- confirm state (fresh page) ----
  try {
    const s = await openAndSelectTwo(browser, W)
    res.confirm.pageErrors = s.pageErrors
    const page = s.page
    const btn = page.getByRole("button", { name: /^prepare payment run/i }).first()
    if ((await btn.count()) === 0) { res.confirm.opened = false; res.confirm.reason = "no Prepare payment run button"; res.confirm.bulkText = (await page.evaluate(measureBar)).innerText; await page.close(); continue }
    if (await btn.isDisabled()) { res.confirm.opened = false; res.confirm.reason = "button disabled"; await page.close(); continue }
    await btn.click()
    const dlg = page.locator("[role=alertdialog], [role=dialog]").first()
    await dlg.waitFor({ timeout: 15000 })
    await page.waitForTimeout(700)
    res.confirm.opened = true
    res.confirm.dialog = await dlg.evaluate(measureDialog)
    await page.screenshot({ path: `${OUT}/confirm-${width}.png`, fullPage: false })
    if (width >= 600) {
      const active = () => page.evaluate(() => { const a = document.activeElement; return a ? { tag: a.tagName.toLowerCase(), type: a.getAttribute("type"), text: (a.textContent || a.getAttribute("aria-label") || "").trim().replace(/\s+/g, " ").slice(0, 80), inDialog: !!a.closest("[role=alertdialog],[role=dialog]") } : null })
      const kb = { activeOnOpen: await active(), tabStops: [] }
      for (let i = 0; i < 6; i++) { await page.keyboard.press("Tab"); await page.waitForTimeout(80); kb.tabStops.push(await active()) }
      kb.allStopsInDialog = kb.tabStops.every((x) => x && x.inDialog)
      res.keyboard = kb
    }
    res.confirm.detect = await detect(page, `confirm@${width}`)
    await page.keyboard.press("Escape")
    await page.waitForTimeout(500)
    res.confirm.closedAfterEscape = (await page.locator("[role=alertdialog], [role=dialog]").count()) === 0
    res.confirm.focusAfterClose = await page.evaluate(() => { const a = document.activeElement; return a ? { tag: a.tagName.toLowerCase(), text: (a.textContent || a.getAttribute("aria-label") || "").trim().slice(0, 80) } : null })
    await page.close()
  } catch (e) { res.confirm.error = String(e.message).split("\n").slice(0, 3).join(" | ") }
}
await browser.close()
report.finishedAt = new Date().toISOString()
fs.writeFileSync(`${OUT}/report.json`, JSON.stringify(report, null, 2))
for (const w in report.widths) {
  const x = report.widths[w]
  console.log(w, "| bulkErr:", x.bulk.error ?? "-", "| confErr:", x.confirm.error ?? "-", "| rows:", x.bulk.rowCount, "| checked:", x.bulk.checkedCount, "| prep:", JSON.stringify(x.bulk.bar?.prepare), "| confirm:", x.confirm.opened, x.confirm.reason ?? "", "| detBulk:", x.bulk.detect ? `${x.bulk.detect.count} (${x.bulk.detect.groups} groups) ${x.bulk.detect.error ?? ""}` : "-", "| detConfirm:", x.confirm.detect ? `${x.confirm.detect.count} (${x.confirm.detect.groups} groups) ${x.confirm.detect.error ?? ""}` : "-")
}
